// ---------- foundations: variables and text styles ----------
async function foundations() {
  for (const [family, style] of [['Onest', 'Regular'], ['Onest', 'Medium'], ['Onest', 'SemiBold'], ['Domine', 'Bold'], ['Caveat', 'Bold']]) {
    await figma.loadFontAsync({ family, style });
  }
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  const collection = collections.find(c => c.name === 'Gustaro') || figma.variables.createVariableCollection('Gustaro');
  const mode = collection.modes[0].modeId;
  const existing = await figma.variables.getLocalVariablesAsync('COLOR');
  for (const [name, value] of Object.entries(DATA.colors)) {
    let v = existing.find(x => x.name === 'color/' + name && x.variableCollectionId === collection.id);
    if (!v) v = figma.variables.createVariable('color/' + name, collection, 'COLOR');
    v.setValueForMode(mode, hex(value));
    v.scopes = ['ALL_SCOPES'];
    V[name] = v;
  }
  const styles = await figma.getLocalTextStylesAsync();
  for (const [name, family, style, size, lineHeight, letterSpacing] of DATA.textStyles) {
    const s = styles.find(x => x.name === name) || figma.createTextStyle();
    s.name = name;
    s.fontName = { family, style };
    s.fontSize = size;
    if (lineHeight) s.lineHeight = { unit: 'PERCENT', value: lineHeight };
    s.letterSpacing = { unit: 'PIXELS', value: letterSpacing };
    TS[name.replace('Gustaro/', '')] = s;
  }
}

