      const cb = figma.createRectangle(); cb.name = 'Checkbox'; cb.resize(24, 24); cb.fills = []; box(cb, 'white', 2); row.appendChild(cb);
      const t = T(parts.map(p => p[0]).join(''), 'Body', 'white', { size: 16, lh: 22 });
      for (const [i, p] of parts.entries()) {
        if (!p[1]) continue;
        const from = parts.slice(0, i).map(q => q[0]).join('').length;
        t.setRangeFontName(from, from + p[0].length, { family: 'Onest', style: 'SemiBold' });
        t.setRangeTextDecoration(from, from + p[0].length, 'UNDERLINE');
      }
      row.appendChild(t); fill(t); t.textAutoResize = 'HEIGHT';
