// ---------- Scan ----------
function scanChrome(s, hint, primaryIsLabel) {
  const row = AL('HORIZONTAL', { name: 'Top', paddingLeft: 16, paddingRight: 16, paddingTop: 8 });
  row.primaryAxisAlignItems = 'SPACE_BETWEEN'; row.counterAxisAlignItems = 'CENTER';
  s.appendChild(row); row.resize(440, 10); row.counterAxisSizingMode = 'AUTO'; row.x = 0; row.y = 62;
  const mk = (ic, size) => {
    const r = figma.createAutoLayout('HORIZONTAL'); r.primaryAxisAlignItems = 'CENTER'; r.counterAxisAlignItems = 'CENTER';
    r.resize(44, 44); r.primaryAxisSizingMode = 'FIXED'; r.counterAxisSizingMode = 'FIXED'; r.cornerRadius = 22; r.fills = [paint('white')];
    r.appendChild(icon(ic, size, 'ink')); return r;
  };
  const x = mk('close', 16); x.name = 'Close'; row.appendChild(x);
  const f = mk('flash', 20); f.name = L('scanTorch'); row.appendChild(f);
  row.primaryAxisSizingMode = 'FIXED';
  const frame = figma.createFrame(); frame.name = 'Viewfinder'; frame.resize(320, 198); frame.fills = []; s.appendChild(frame); frame.x = 60; frame.y = 300;
  for (const [cx, cy, sides] of [[0, 0, 'tl'], [296, 0, 'tr'], [0, 174, 'bl'], [296, 174, 'br']]) {
    const k = figma.createFrame(); k.name = 'Corner'; k.resize(24, 24); k.fills = []; k.clipsContent = false; frame.appendChild(k); k.x = cx; k.y = cy;
    border(k, [sides.includes('t') ? 't' : 'b', sides.includes('l') ? 'l' : 'r'].join(''), 'white', 4);
  }
  const hintT = T(hint, 'Button', 'white', { align: 'CENTER' }); s.appendChild(hintT); hintT.textAutoResize = 'HEIGHT'; hintT.resize(360, hintT.height); hintT.x = 40; hintT.y = 540;
  const bar = AL('HORIZONTAL', { name: 'Actions', itemSpacing: 10, paddingLeft: 20, paddingRight: 20 }); s.appendChild(bar);
  bar.resize(440, 56); bar.primaryAxisSizingMode = 'FIXED'; bar.x = 0; bar.y = 956 - 56 - 36;
  const a = button(primaryIsLabel ? 'Primary' : 'Outline', L('scanReadLabel')); bar.appendChild(a); fill(a);
  const b = button('Outline', L('scanEnterCode')); bar.appendChild(b); fill(b);
}
