// ---------- Add a wine bottle ----------
function addBottle() {
  const s = screen('13 Add a wine bottle', 3000);
  appBar(s, L('addTitle'));
  const c = content(s, 118, { itemSpacing: 0, paddingTop: 4 });
  const intro = AL('VERTICAL', { name: 'Intro', padding: 12 }); intro.paddingLeft = intro.paddingRight = intro.paddingTop = intro.paddingBottom = 12; intro.fills = [paint('surface')];
  c.appendChild(intro); fill(intro); intro.appendChild(wrapText(T(L('addIntro'), 'Small', 'text-soft')));
  const head = text => { c.appendChild(gap(24)); c.appendChild(T(text, 'Title', 'ink', { size: 22 })); c.appendChild(gap(10)); };
  const field = (label, required, value = '', helper = '') => {
    const f = setP(inst('Field'), { Label: required ? label + ' *' : label, Value: value || ' ' });
    if (helper) setP(f, { Helper: helper, 'Show helper': true });
    c.appendChild(f); fill(f); c.appendChild(gap(14)); return f;
  };
  const twoUp = (a, b) => {
    const row = AL('HORIZONTAL', { name: 'Pair', itemSpacing: 12 }); c.appendChild(row); fill(row);
    for (const label of [a, b]) { const f = setP(inst('Field'), { Label: label, Value: ' ' }); row.appendChild(f); fill(f); }
    c.appendChild(gap(14));
  };
  head(L('addSectionPhoto'));
  c.appendChild(wrapText(T(L('addPhotoHelp'), 'Small', 'text-soft'))); c.appendChild(gap(10));
  const pr = AL('HORIZONTAL', { name: 'Photo buttons', itemSpacing: 8 }); c.appendChild(pr); fill(pr);
  for (const l of [L('addPhotoTake'), L('addPhotoChoose')]) { const b = button('Outline', l); pr.appendChild(b); fill(b); b.resize(b.width, 48); b.layoutSizingVertical = 'FIXED'; }
  head(L('addSectionBarcode'));
  field(L('addBarcode'), false, '4841000000029', L('addBarcodeHelp'));
  field(L('addBottleSize'), false, '750');
  head(L('addSectionWine'));
  field(L('addWinery'), true); field(L('addWineName'), true);
  c.appendChild(T(L('addType') + ' *', 'Label')); c.appendChild(gap(6));
  const types = AL('HORIZONTAL', { name: 'Types', itemSpacing: 8 }); types.layoutWrap = 'WRAP'; types.counterAxisSpacing = 8; c.appendChild(types); fill(types);
  for (const k of ['typeRed', 'typeWhite', 'typeRose', 'typeOrange', 'typeSparkling', 'typeDessert']) {
    const ch = setP(variant('Chip', 'Selected=No'), { Label: L(k) }); types.appendChild(ch); ch.resize(ch.width, 40);
  }
  c.appendChild(gap(14));
  field(L('addYear'), true); field(L('addRegion'), false, L('addRegionHint')); field(L('addGrapes'), false, L('addGrapesHint'));
  head(L('addSectionSpecs'));
  twoUp(L('addAbv'), L('addAcidity')); twoUp(L('addSugar'), L('addTannins'));
  head(L('addSectionTasting'));
  field(L('addSensory'), false, L('addSensoryHint')); field(L('addPairings'), false, L('addPairingsHint')); field(L('addDescription'), false);
  c.appendChild(gap(24));
  finish(s, c, 118, 90);
  const bar = AL('VERTICAL', { name: 'Save bar', paddingLeft: 20, paddingRight: 20, paddingTop: 12, paddingBottom: 12 }); bar.fills = [paint('white')]; border(bar, 't', 'line');
  s.appendChild(bar); bar.resize(440, 10); bar.counterAxisSizingMode = 'FIXED'; bar.primaryAxisSizingMode = 'AUTO';
  const b = button('Primary', L('addSave')); bar.appendChild(b); fill(b);
  bar.x = 0; bar.y = s.height - bar.height;
  place(s); return s;
}

// ---------- Terms and Privacy (text from the app) ----------
function legal(name, titleText, md) {
  const s = screen(name, 2400);
  appBar(s, titleText);
  const c = content(s, 118, { itemSpacing: 0 });
  for (const raw of md.split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('# ')) continue;
    if (line.startsWith('## ')) { c.appendChild(gap(18)); c.appendChild(wrapText(T(line.slice(3), 'Card title'))); c.appendChild(gap(6)); continue; }
    const bullet = line.startsWith('- ');
    const t = T((bullet ? '•  ' : '') + line.replace(/\*\*/g, ''), 'Body', 'ink', { lh: 22 });
    c.appendChild(wrapText(t)); c.appendChild(gap(8));
  }
  c.appendChild(gap(40));
  finish(s, c, 118, 0); place(s);
  return s;
}

// ---------- run ----------
async function main() {
  const page = figma.root.children.find(p => p.name === PAGE_NAME) || figma.createPage();
  page.name = PAGE_NAME;
  await figma.setCurrentPageAsync(page);
  for (const n of [...page.children]) n.remove();
  await foundations();

  const board = figma.createFrame(); board.name = 'Components'; board.fills = [paint('white')];
  board.layoutMode = 'HORIZONTAL'; board.layoutWrap = 'WRAP'; board.itemSpacing = 40; board.counterAxisSpacing = 40;
  board.paddingLeft = board.paddingRight = board.paddingTop = board.paddingBottom = 40;
  board.resize(1800, 100); board.primaryAxisSizingMode = 'FIXED'; board.counterAxisSizingMode = 'AUTO';
  board.x = -2000; board.y = 120;
  page.appendChild(board);
  await makeComponents(board);

  SECTION = figma.createSection(); SECTION.name = 'Gustaro app — as built'; page.appendChild(SECTION);
  const failed = [];
  const run = (name, fn, newRowBefore) => { if (newRowBefore) newRow(); try { fn(); } catch (e) { failed.push(name + ': ' + e.message); } };
  run('onboarding', () => { for (let i = 0; i < 4; i++) onboarding(i); }, false);
  run('home', home, true); run('explore', explore); run('wines', wines); run('more', more);
  run('wine', wine, true); run('miss', miss); run('scan', scan); run('scanNoCamera', scanNoCamera); run('scanManual', scanManual);
  run('myBottles', myBottles, true); run('about', about); run('addBottle', addBottle);
  run('tasting', () => { for (let i = 0; i < 5; i++) tasting(i); }, true);
  run('terms', () => legal('14 Terms & Conditions', L('moreTerms'), DATA.terms), true);
  run('privacy', () => legal('15 Privacy Policy', L('morePrivacy'), DATA.privacy));

  const kids = SECTION.children;
  let right = 0, bottom = 0;
  for (const k of kids) { right = Math.max(right, k.x + k.width); bottom = Math.max(bottom, k.y + k.height); }
  SECTION.resizeWithoutConstraints(right + 80, bottom + 120);
  SECTION.x = 0; SECTION.y = 0;
  figma.viewport.scrollAndZoomIntoView([SECTION]);
  return failed.length ? 'Built with problems: ' + failed.join(' | ') : 'Done: ' + kids.length + ' screens and the components are in "' + PAGE_NAME + '".';
}
main().then(msg => figma.closePlugin(msg)).catch(e => figma.closePlugin('Failed: ' + e.message));
